/* CM1 base address */
pub const OMAP54XX_CM_CORE_AON_BASE: u32 = 0x4a00_4000;

#[macro_export]
macro_rules! OMAP54XX_CM_CORE_AON_REGADDR {
    ($inst:expr, $reg:expr) => {
        OMAP2_L4_IO_ADDRESS(
            OMAP54XX_CM_CORE_AON_BASE
                .wrapping_add($inst)
                .wrapping_add($reg),
        )
    };
}

